params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
$expected=[ordered]@{
 'fix/updater-release-gate-governance-20260929'='6f54623190e3af6dd0e111778ec60e38db1ee48a'
 'fix/updater-release-gate-verification-20260929'='5108f92476c13ccb44538124c234afbb314c0acb'
}
git -C $repo fetch origin --prune
$deleted=@();$skipped=@()
foreach($b in $expected.Keys){
 $line=(git -C $repo ls-remote origin "refs/heads/$b")
 if(-not $line){$skipped += [pscustomobject]@{branch=$b;reason='absent'};continue}
 $actual=(($line.Trim()) -split '\s+')[0]
 if($actual -ne $expected[$b]){$skipped += [pscustomobject]@{branch=$b;reason='moved';actual=$actual};continue}
 git -C $repo push origin --delete $b
 if($LASTEXITCODE -ne 0){throw "delete failed $b"}
 $deleted += $b
}
[pscustomobject]@{deleted=$deleted;skipped=$skipped}|ConvertTo-Json -Depth 4
